public int process(int a, int b) {
    int result = 0;
    if (a > 0) { // Diem quyet dinh 1
        result += a;
    }
    if (b > 0) { // Diem quyet dinh 2
        result += b;
    }
    for (int i = 0; i < a; i++) { // Diem quyet dinh 3
        result++;
    }
    return result;
}

